package controlplane

import (
	"context"
	"database/sql"
	"sort"
)

// Paths remain private CLI inputs. Only backup IDs generated by the old
// program are opened relative to the owned, no-follow directory descriptor.
type MigrationFinalMappingInput struct {
	WebsiteBackupDirectories map[string]string `json:"-"`
}
type migrationFinalRevision struct{ Role, ID, SourceID, Source, Alias string }
type MigrationFinalMappingReport struct {
	Session         string                            `json:"session"`
	Batch           string                            `json:"batch"`
	SessionVersion  int64                             `json:"session_version"`
	Added           int64                             `json:"added"`
	Modified        int64                             `json:"modified"`
	Deleted         int64                             `json:"deleted"`
	Unchanged       int64                             `json:"unchanged"`
	Pending         []MigrationReconciliationConflict `json:"pending"`
	Conflicts       []MigrationReconciliationConflict `json:"conflicts"`
	Complete        bool                              `json:"complete"`
	Protected       bool                              `json:"protected"`
	ReadyForCutover bool                              `json:"ready_for_cutover"`
}

// Parents precede their children. Historical node identities are shared and
// retained, never claimed or removed by this mapper.
var migrationFinalTables = []string{"v3_accounts", "v3_sessions", "v3_websites", "v3_website_incidents", "v3_website_outbox", "v3_event_keys", "v3_events", "v3_imported_events", "v3_health_rules", "v3_health_events", "v3_health_batches", "v3_health_outbox", "v3_notifications", "v3_notification_attempts", "v3_notification_public", "v3_notification_rates", "v3_website_backups", "v3_audit"}
var migrationFinalScratchTables = []string{"v3_node_identities", "v3_legacy_records", "v3_imports"}

func migrationFinalRevisionsTx(ctx context.Context, tx *sql.Tx, state MigrationSession) ([]migrationFinalRevision, error) {
	out := []migrationFinalRevision{}
	for _, role := range state.Roles {
		var r migrationFinalRevision
		r.Role = role
		var revisionState string
		e := tx.QueryRowContext(ctx, `SELECT id,source_id,snapshot_sha256,state FROM v3_migration_revisions WHERE session=$1 AND role=$2 ORDER BY sequence DESC LIMIT 1`, state.ID, role).Scan(&r.ID, &r.SourceID, &r.Source, &revisionState)
		if e != nil || revisionState != "ready" || verifyMigrationRevisionIndex(ctx, tx, r.ID) != nil {
			return nil, ErrMigrationSession
		}
		r.Alias = digest([]byte("v2-domain-source:" + state.ID + ":" + r.Role + ":" + r.SourceID))
		out = append(out, r)
	}
	return out, nil
}
func migrationFinalQualified(schema, table string) string {
	return quotePG(schema) + "." + quotePG(table)
}

func migrationFinalScratchTx(ctx context.Context, tx *sql.Tx, live, scratch string) error {
	if _, e := tx.ExecContext(ctx, `CREATE SCHEMA `+quotePG(scratch)); e != nil {
		return e
	}
	for _, table := range append(append([]string{}, migrationFinalTables...), migrationFinalScratchTables...) {
		if _, e := tx.ExecContext(ctx, `CREATE TABLE `+migrationFinalQualified(scratch, table)+` (LIKE `+migrationFinalQualified(live, table)+` INCLUDING ALL)`); e != nil {
			return e
		}
	}
	_, e := tx.ExecContext(ctx, `SELECT set_config('search_path',$1,true)`, quotePG(scratch)+","+quotePG(live))
	return e
}
func migrationFinalArchiveTablesTx(ctx context.Context, tx *sql.Tx, live string, r migrationFinalRevision) (map[string]int64, error) {
	rows, e := tx.QueryContext(ctx, `SELECT table_name,count,complete FROM `+migrationFinalQualified(live, "v3_imports")+` WHERE source=$1 ORDER BY table_name`, r.Source)
	if e != nil {
		return nil, e
	}
	tables := map[string]int64{}
	for rows.Next() {
		var name string
		var count int64
		var complete bool
		if e = rows.Scan(&name, &count, &complete); e != nil || !complete {
			rows.Close()
			return nil, ErrMigrationSession
		}
		tables[name] = count
	}
	e = rows.Err()
	rows.Close()
	if e != nil {
		return nil, e
	}
	if _, e = tx.ExecContext(ctx, `INSERT INTO v3_legacy_records SELECT $1,table_name,record_key,payload,digest FROM `+migrationFinalQualified(live, "v3_legacy_records")+` WHERE source=$2`, r.Alias, r.Source); e != nil {
		return nil, e
	}
	return tables, nil
}

func migrationFinalRecordsTx(ctx context.Context, tx *sql.Tx, source, table string, mapRecord func(archivedRecord) error) error {
	var cursor string
	for {
		rows, e := tx.QueryContext(ctx, `SELECT record_key,payload,digest FROM v3_legacy_records WHERE source=$1 AND table_name=$2 AND ($3='' OR record_key::bigint>NULLIF($3,'')::bigint) ORDER BY record_key::bigint LIMIT 500`, source, table, cursor)
		if e != nil {
			return e
		}
		type entry struct {
			key  string
			raw  []byte
			hash string
		}
		batch := []entry{}
		for rows.Next() {
			var v entry
			if e = rows.Scan(&v.key, &v.raw, &v.hash); e != nil {
				break
			}
			batch = append(batch, v)
		}
		if e == nil {
			e = rows.Err()
		}
		rows.Close()
		if e != nil {
			return e
		}
		for _, v := range batch {
			r, e := decodedArchiveRecord(v.raw, v.hash)
			if e != nil {
				return e
			}
			if e = mapRecord(r); e != nil {
				return e
			}
			cursor = v.key
		}
		if len(batch) < 500 {
			return nil
		}
	}
}

// Build candidates per the actual v2 database responsibilities: events-v1
// owns receiver/web/notification data, metrics-v1 owns host health/history,
// and management.sqlite3 owns deployment/watchdog/configuration records.
func migrationFinalBuildCandidatesTx(ctx context.Context, tx *sql.Tx, live string, revisions []migrationFinalRevision, in MigrationFinalMappingInput, metricVerified, historyVerified map[string]bool) (map[string]int64, error) {
	pending := map[string]int64{}
	for _, r := range revisions {
		tables, e := migrationFinalArchiveTablesTx(ctx, tx, live, r)
		if e != nil {
			return nil, e
		}
		known := map[string]bool{}
		for _, table := range []string{"website_admin", "website_sessions", "websites", "website_incidents", "website_outbox", "events", "migrated_logs", "tasks", "email_recipients", "delivery_records", "email_attempts", "kv", "health_rules", "health_events", "alert_batches", "alert_outbox", "alert_members", "record_operations", "retention_jobs", "website_backups"} {
			known[table] = true
		}
		for table, count := range tables {
			if count > 0 && !known[table] {
				if expectedRole, supported := migrationLegacyHistoryTables[table]; supported {
					if r.Role != expectedRole {
						pending["legacy_history_in_wrong_source_role"] += count
					} else if !historyVerified[r.ID] {
						pending["legacy_history_requires_verified_mapping"] += count
					}
					continue
				}
				switch table {
				case "samples":
					if !metricVerified[r.ID] {
						pending["legacy_metrics_history_requires_replay"] += count
					}
				case "baselines", "migrations", "import_guards":
					// Counter-reset baselines and old import bookkeeping stay in
					// the complete archive; they are never today's live counters.
				case "jobs", "logs", "config_backups", "config_backup_details", "config_backup_previews", "job_archives", "backup_import_attempts":
					pending["legacy_host_jobs_or_artifacts_require_mapping"] += count
				case "watchdog_state", "watchdog_outbox":
					pending["legacy_watchdog_state_requires_mapping"] += count
				case "website_backup_pins", "website_incident_origins", "probes":
					pending["legacy_auxiliary_state_requires_review"] += count
				default:
					pending["unmapped_legacy_table"] += count
				}
			}
		}
		// A table in the wrong database is never silently assigned the other
		// database's identity. Keep its complete archive and block activation.
		for _, table := range []string{"website_admin", "website_sessions", "websites", "website_incidents", "website_outbox", "events", "migrated_logs", "tasks", "email_recipients", "delivery_records", "email_attempts", "kv", "website_backups"} {
			if _, exists := tables[table]; exists && r.Role != "central" {
				pending["legacy_domain_in_wrong_source_role"] += tables[table] + 1
				delete(tables, table)
			}
		}
		for _, table := range []string{"health_rules", "health_events", "alert_batches", "alert_outbox", "alert_members"} {
			if _, exists := tables[table]; exists && r.Role != "health" {
				pending["legacy_domain_in_wrong_source_role"] += tables[table] + 1
				delete(tables, table)
			}
		}
		for _, table := range []string{"website_admin", "website_sessions", "websites", "website_incidents", "website_outbox"} {
			if _, ok := tables[table]; ok {
				if e = migrationFinalRecordsTx(ctx, tx, r.Alias, table, func(rec archivedRecord) error { _, e := mapWebsiteRecord(ctx, tx, r.Alias, table, rec); return e }); e != nil {
					return nil, e
				}
			}
		}
		for _, table := range []string{"events", "migrated_logs"} {
			if _, ok := tables[table]; ok {
				if _, queue := tables["tasks"]; !queue {
					pending["legacy_event_queue_evidence_missing"] += tables[table] + 1
					continue
				}
				if e = migrationFinalRecordsTx(ctx, tx, r.Alias, table, func(rec archivedRecord) error { _, e := mapEventRecord(ctx, tx, r.Alias, table, rec); return e }); e != nil {
					return nil, e
				}
			}
		}
		for _, table := range []string{"tasks", "email_recipients", "delivery_records", "email_attempts", "kv"} {
			if _, ok := tables[table]; ok {
				if e = migrationFinalRecordsTx(ctx, tx, r.Alias, table, func(rec archivedRecord) error { _, e := mapNotificationRecord(ctx, tx, r.Alias, table, rec); return e }); e != nil {
					return nil, e
				}
			}
		}
		for _, table := range []string{"health_rules", "health_events", "alert_batches", "alert_outbox", "alert_members"} {
			if _, ok := tables[table]; ok {
				if e = migrationFinalRecordsTx(ctx, tx, r.Alias, table, func(rec archivedRecord) error { _, e := mapHealthRecord(ctx, tx, table, rec); return e }); e != nil {
					return nil, e
				}
			}
		}
		for _, table := range []string{"record_operations", "retention_jobs"} {
			if _, ok := tables[table]; ok {
				if e = migrationFinalRecordsTx(ctx, tx, r.Alias, table, func(rec archivedRecord) error {
					_, e := mapOperationAuditRecord(ctx, tx, r.Alias, table, rec)
					return e
				}); e != nil {
					return nil, e
				}
			}
		}
		if count, ok := tables["website_backups"]; ok && count > 0 {
			directory := in.WebsiteBackupDirectories[r.Role]
			if directory == "" {
				pending["legacy_website_backup_files_missing"] += count
				continue
			}
			dir, e := privateDirectory(directory)
			if e != nil {
				return nil, ErrMigrationSession
			}
			e = migrationFinalRecordsTx(ctx, tx, r.Alias, "website_backups", func(rec archivedRecord) error { _, e := mapWebsiteBackupRecord(ctx, tx, r.Alias, dir, rec); return e })
			dir.Close()
			if e != nil {
				return nil, e
			}
		}
	}
	if e := migrationFinalHealthLinksTx(ctx, tx); e != nil {
		return nil, e
	}
	return pending, nil
}

func migrationFinalHealthLinksTx(ctx context.Context, tx *sql.Tx) error {
	var bad bool
	if e := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM v3_health_batches b WHERE (b.done_at IS NULL AND (NOT EXISTS(SELECT 1 FROM v3_health_outbox o WHERE o.batch=b.id) OR (SELECT count(*) FROM v3_health_outbox o WHERE o.batch=b.id)>500)) OR EXISTS(SELECT 1 FROM v3_health_outbox o WHERE o.batch=b.id AND (o.node<>b.node OR o.phase<>b.phase OR (o.done_at IS NULL)<>(b.done_at IS NULL))))`).Scan(&bad); e != nil || bad {
		return ErrMigrationSession
	}
	if e := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM v3_notifications n JOIN v3_health_batches b ON n.event_id='server-alert:'||b.id WHERE n.node<>b.node OR n.payload->>'node_id' IS DISTINCT FROM b.node OR n.payload->>'notice_kind' IS DISTINCT FROM b.phase OR n.payload->>'message' IS DISTINCT FROM b.message)`).Scan(&bad); e != nil || bad {
		return ErrMigrationSession
	}
	if _, e := tx.ExecContext(ctx, `UPDATE v3_health_batches b SET done_at=q.admitted FROM (SELECT event_id,min(created_at) admitted FROM v3_notifications GROUP BY event_id) q WHERE q.event_id='server-alert:'||b.id AND b.done_at IS NULL`); e != nil {
		return e
	}
	_, e := tx.ExecContext(ctx, `UPDATE v3_health_outbox o SET done_at=b.done_at,result='从旧告警出箱迁入并核对原通知' FROM v3_health_batches b WHERE o.batch=b.id AND o.done_at IS NULL AND b.done_at IS NOT NULL`)
	return e
}

func migrationFinalIssues(values map[string]int64) []MigrationReconciliationConflict {
	out := []MigrationReconciliationConflict{}
	for category, count := range values {
		if count > 0 {
			out = append(out, MigrationReconciliationConflict{category, count})
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Category < out[j].Category })
	return out
}
